    16	public class ReportController {
    17	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE;
    18	    private static final DateTimeFormatter MONTH_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM");
    19	
    20	    private final RoomRepository roomRepository;
    21	    private final ReservationRepository reservationRepository;
    22	
    23	    public ReportController(RoomRepository roomRepository, ReservationRepository reservationRepository) {
    24	        this.roomRepository = roomRepository;
    25	        this.reservationRepository = reservationRepository;
    26	    }
    27	
    28	    public void getOccupancyReport(Context ctx) {
    29	        String dateParam = ctx.queryParam("date");
    30	        if (dateParam == null || dateParam.isBlank()) {
    31	            throw new ApiException(400, "INVALID_REQUEST", "Date parameter is required");
    32	        }
    33	
    34	        LocalDate date = parseDate(dateParam);
    35	        List<Reservation> reservations = reservationRepository.findPaidReservationsForNight(date);
    36	        int totalRooms = roomRepository.findAll().size();
    37	
    38	        StringBuilder csv = new StringBuilder();
    39	        csv.append("room,type,reservation,check_in,check_out\n");
    40	
    41	        for (Reservation reservation : reservations) {
    42	            csv.append(String.format("%s,%s,%d,%s,%s\n",
    43	                reservation.getRoomNumber(),
    44	                reservation.getRoomType().name(),
    45	                reservation.getId(),
    46	                reservation.getCheckIn().format(DATE_FORMAT),
    47	                reservation.getCheckOut().format(DATE_FORMAT)
    48	            ));
    49	        }
    50	
    51	        csv.append(String.format("total,%d/%d\n", reservations.size(), totalRooms));
    52	
    53	        ctx.contentType("text/csv; charset=utf-8")
    54	           .result(csv.toString());
    55	    }
    56	
    57	    public void getRevenueReport(Context ctx) {
    58	        String monthParam = ctx.queryParam("month");
    59	        if (monthParam == null || monthParam.isBlank()) {
    60	            throw new ApiException(400, "INVALID_REQUEST", "Month parameter is required");
    61	        }
    62	
    63	        YearMonth yearMonth = parseMonth(monthParam);
    64	        List<Reservation> reservations = reservationRepository.findReservationsForRevenueReport(
    65	            yearMonth.getYear(), yearMonth.getMonthValue()
    66	        );
    67	
    68	        StringBuilder csv = new StringBuilder();
    69	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    70	
    71	        BigDecimal total = BigDecimal.ZERO;
    72	
    73	        for (Reservation reservation : reservations) {
    74	            BigDecimal amount = reservation.getAmountPaid();
    75	            if (reservation.getRefund() != null) {
    76	                amount = amount.subtract(reservation.getRefund());
    77	            }
    78	
    79	            csv.append(String.format("%d,%s,%s,%s,%s,%.2f\n",
    80	                reservation.getId(),
    81	                reservation.getRoomNumber(),
    82	                reservation.getCheckIn().format(DATE_FORMAT),
    83	                reservation.getCheckOut().format(DATE_FORMAT),
    84	                reservation.getStatus().name(),
    85	                amount.doubleValue()
    86	            ));
    87	
    88	            total = total.add(amount);
    89	        }
    90	
    91	        csv.append(String.format("total,%.2f\n", total.doubleValue()));
    92	
    93	        ctx.contentType("text/csv; charset=utf-8")
    94	           .result(csv.toString());
    95	    }
    96	
    97	    private LocalDate parseDate(String date) {
    98	        try {
    99	            return LocalDate.parse(date, DATE_FORMAT);
   100	        } catch (DateTimeParseException e) {
   101	            throw new ApiException(400, "INVALID_REQUEST", "Invalid date format, expected yyyy-MM-dd");
   102	        }
   103	    }
   104	
   105	    private YearMonth parseMonth(String month) {
   106	        try {
   107	            return YearMonth.parse(month, MONTH_FORMAT);
   108	        } catch (DateTimeParseException e) {
   109	            throw new ApiException(400, "INVALID_REQUEST", "Invalid month format, expected yyyy-MM");
   110	        }
   111	    }
   112	}
