    18	public class ReservationController {
    19	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE;
    20	
    21	    private final RoomRepository roomRepository;
    22	    private final ReservationRepository reservationRepository;
    23	    private final List<ReservationObserver> observers;
    24	
    25	    public ReservationController(
    26	        RoomRepository roomRepository,
    27	        ReservationRepository reservationRepository,
    28	        List<ReservationObserver> observers
    29	    ) {
    30	        this.roomRepository = roomRepository;
    31	        this.reservationRepository = reservationRepository;
    32	        this.observers = observers;
    33	    }
    34	
    35	    public void createReservation(Context ctx) {
    36	        CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
    37	
    38	        validateRequest(request);
    39	
    40	        Room room = roomRepository.findByNumber(request.roomNumber())
    41	            .orElseThrow(() -> new ApiException(404, "ROOM_NOT_FOUND", "Room not found"));
    42	
    43	        LocalDate checkIn = parseDate(request.checkIn());
    44	        LocalDate checkOut = parseDate(request.checkOut());
    45	
    46	        if (!checkOut.isAfter(checkIn)) {
    47	            throw new ApiException(400, "INVALID_REQUEST", "Check-out must be after check-in");
    48	        }
    49	
    50	        if (request.guests() < 1) {
    51	            throw new ApiException(400, "INVALID_REQUEST", "At least one guest is required");
    52	        }
    53	
    54	        if (request.guests() > room.getCapacity()) {
    55	            throw new ApiException(422, "CAPACITY_EXCEEDED", "Number of guests exceeds room capacity");
    56	        }
    57	
    58	        RatePlan ratePlan;
    59	        try {
    60	            ratePlan = RatePlan.valueOf(request.ratePlan());
    61	        } catch (IllegalArgumentException e) {
    62	            throw new ApiException(400, "INVALID_REQUEST", "Invalid rate plan");
    63	        }
    64	
    65	        List<Reservation> conflicting = reservationRepository.findByRoomAndDateRange(
    66	            request.roomNumber(), checkIn, checkOut
    67	        );
    68	
    69	        if (!conflicting.isEmpty()) {
    70	            throw new ApiException(409, "ROOM_UNAVAILABLE", "Room is not available for the selected dates");
    71	        }
    72	
    73	        Reservation reservation = new Reservation(
    74	            request.roomNumber(),
    75	            room.getType(),
    76	            request.guestName(),
    77	            request.guestEmail(),
    78	            request.guestCpf(),
    79	            checkIn,
    80	            checkOut,
    81	            request.guests(),
    82	            ratePlan
    83	        );
    84	
    85	        for (ReservationObserver observer : observers) {
    86	            reservation.addObserver(observer);
    87	        }
    88	
    89	        reservationRepository.save(reservation);
    90	
    91	        ctx.status(201).json(ReservationResponse.from(reservation));
    92	    }
    93	
    94	    public void getReservation(Context ctx) {
    95	        long id = parseLongPathParam(ctx, "id");
    96	
    97	        Reservation reservation = reservationRepository.findById(id)
    98	            .orElseThrow(() -> new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found"));
    99	
   100	        ctx.json(ReservationResponse.from(reservation));
   101	    }
   102	
   103	    public void confirmReservation(Context ctx) {
   104	        long id = parseLongPathParam(ctx, "id");
   105	
   106	        Reservation reservation = reservationRepository.findById(id)
   107	            .orElseThrow(() -> new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found"));
   108	
   109	        try {
   110	            reservation.confirm();
   111	            reservationRepository.save(reservation);
   112	        } catch (IllegalStateException e) {
   113	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", e.getMessage());
   114	        }
   115	
   116	        ctx.json(ReservationResponse.from(reservation));
   117	    }
