   115	    public void cancel() {
   116	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
   117	            throw new IllegalStateException("Only pending or confirmed reservations can be cancelled");
   118	        }
   119	
   120	        boolean wasConfirmed = (status == ReservationStatus.CONFIRMED);
   121	
   122	        if (wasConfirmed && ratePlan.isRefundable()) {
   123	            this.refund = amountPaid;
