     8	    public static boolean isHighSeason(LocalDate date) {
     9	        Month month = date.getMonth();
    10	        int day = date.getDayOfMonth();
    11	
    12	        if (month == Month.JULY) {
    13	            return true;
    14	        }
    15	
    16	        if (month == Month.DECEMBER && day >= 15) {
    17	            return true;
    18	        }
    19	
    20	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    21	            return true;
    22	        }
    23	
    24	        return false;
    25	    }
    26	}

